#include <new>

bool indice_valido(int indice) {
    return indice == 0 || indice == 1;
}

class Deposito {
public:
    bool hay(int indice) const {
        return indice == 0 ? primero_ != nullptr : segundo_ != nullptr;
    }

    int valor(int indice) const {
        return indice == 0 ? *primero_ : *segundo_;
    }

    bool poner(int indice, int valor);
    bool cambiar(int indice, int valor);
    bool vaciar(int indice);
    bool transferir(int origen, int destino);
private:
    std::unique_ptr<int>& elegir(int indice) {
        return indice == 0 ? primero_ : segundo_;
    }
    std::unique_ptr<int> primero_ = std::make_unique<int>(4);
    std::unique_ptr<int> segundo_ = std::make_unique<int>(7);
};

bool Deposito::poner(int indice, int valor) {
    if (!indice_valido(indice) || valor < 0 || valor > 9) {
        return false;
    }
    try {
        auto candidato = std::make_unique<int>(valor);
        elegir(indice).swap(candidato);
        return true;
    } catch (const std::bad_alloc&) {
        return false;
    }
}

bool Deposito::cambiar(int indice, int valor) {
    if (!indice_valido(indice) || valor < 0 || valor > 9) {
        return false;
    }
    auto& propietario = elegir(indice);
    if (!propietario) {
        return false;
    }
    *propietario = valor;
    return true;
}

bool Deposito::vaciar(int indice) {
    if (!indice_valido(indice)) {
        return false;
    }
    elegir(indice).reset();
    return true;
}

bool Deposito::transferir(int origen, int destino) {
    // Completa las comprobaciones y la transferencia, sin crear otro entero.
    (void)origen;
    (void)destino;
    return false;
}

void mostrar_dato(bool hay, int valor) {
    if (hay) {
        std::cout << valor;
    } else {
        std::cout << 'X';
    }
}

void mostrar(const Deposito& deposito) {
    for (int indice = 0; indice < 2; ++indice) {
        if (indice != 0) {
            std::cout << ':';
        }
        const bool hay = deposito.hay(indice);
        mostrar_dato(hay, hay ? deposito.valor(indice) : 0);
    }
}

