    mostrar(deposito);
    std::cout << '\n';
    for (int i = 0; i < cantidad; ++i) {
        int operacion = 0;
        int a = 0;
        int b = 0;

        if (!(std::cin >> operacion >> a >> b)) {
            return 1;
        }
        const bool habia0 = deposito.hay(0);
        const bool habia1 = deposito.hay(1);
        const int anterior0 = habia0 ? deposito.valor(0) : 0;
        const int anterior1 = habia1 ? deposito.valor(1) : 0;
        bool aceptado = false;

        if (operacion == 1) {
            aceptado = deposito.transferir(a, b);
        } else if (operacion == 2) {
            aceptado = deposito.poner(a, b);
        } else if (operacion == 3) {
            aceptado = deposito.vaciar(a);
        } else if (operacion == 4) {
            aceptado = deposito.cambiar(a, b);
        }
        std::cout << "Resultado:" << aceptado << ";Antes:";
        mostrar_dato(habia0, anterior0);
        std::cout << ':';
        mostrar_dato(habia1, anterior1);
        std::cout << ";Actual:";
        mostrar(deposito);
        std::cout << '\n';
    }
    std::cout << "Final:";
    mostrar(deposito);
